<?php

declare(strict_types=1);

require_once dirname(__DIR__, 2) . '/includes/layout.php';
require_once dirname(__DIR__, 2) . '/includes/discord_bots.php';

$key = (string) ($_GET['feature'] ?? $_POST['feature'] ?? '');
$featureMap = [];
foreach (discord_bots_default_features() as $item) $featureMap[$item['key']] = $item;
$featureMap['user-permissions'] = ['key' => 'user-permissions', 'name' => 'User Permissions', 'description' => '', 'path' => '/users', 'category' => 'Access Control', 'icon' => 'user-cog', 'mode' => 'Manage'];
$featureMap['permission-templates'] = ['key' => 'permission-templates', 'name' => 'Permission Templates', 'description' => '', 'path' => '/group-permissions', 'category' => 'Access Control', 'icon' => 'copy-check', 'mode' => 'Manage'];
$featureMap['applicant-detail'] = ['key' => 'applicant-detail', 'name' => 'Applicant History', 'description' => '', 'path' => '/applicants', 'category' => 'Applications', 'icon' => 'history', 'mode' => 'View'];
if (!isset($featureMap[$key]) || $key === 'overview') { header('Location: /discord-bots/management/'); exit; }
$feature = $featureMap[$key];
$error = null;
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    try {
        if (!auth_verify_csrf((string) ($_POST['csrf_token'] ?? ''))) throw new RuntimeException('This session expired. Refresh and try again.');
        $message = discord_bots_management_action((string) ($_POST['action'] ?? ''), $_POST);
        $userQuery = $key === 'user-permissions' ? '&user_id=' . rawurlencode((string) ($_POST['user_id'] ?? '')) : '';
        header('Location: /discord-bots/management/feature.php?feature=' . rawurlencode($key) . $userQuery . '&saved=' . rawurlencode($message));
        exit;
    } catch (Throwable $exception) { $error = $exception->getMessage(); }
}
try { $data = discord_bots_management_data($key, $_GET); }
catch (Throwable $exception) { $data = []; $error ??= $exception->getMessage(); }
$settings = project_settings('discordbots');
$escape = static fn(mixed $value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$formStart = static function (string $action) use ($key, $escape): void { ?><form class="management-inline-form" method="post"><input type="hidden" name="csrf_token" value="<?= $escape(auth_csrf_token()) ?>"><input type="hidden" name="feature" value="<?= $escape($key) ?>"><input type="hidden" name="action" value="<?= $escape($action) ?>"><?php };
dashboard_header($settings['title'] . ': ' . $feature['name'], 'discord-bots-management', 'discordbots');
?>
<section class="view active">
    <div class="section-title project-title"><span><small>BOT MANAGEMENT</small><h1><?= $escape(strtoupper($feature['name'])) ?></h1></span><div class="title-actions"><a class="secondary-button" href="/discord-bots/management/"><i data-lucide="arrow-left"></i>All features</a><a class="secondary-button" href="<?= $escape(discord_bots_feature_url($feature['path'])) ?>" target="_blank" rel="noreferrer"><i data-lucide="external-link"></i>Open Professor</a></div></div>
    <?php if (isset($_GET['saved'])): ?><div class="flash success"><i data-lucide="circle-check"></i><?= $escape($_GET['saved']) ?></div><?php endif; ?>
    <?php if ($error): ?><div class="flash error"><i data-lucide="circle-alert"></i><?= $escape($error) ?><?= str_contains($error, 'Discord user ID') ? ' Open Account settings to link it.' : '' ?></div><?php endif; ?>

    <?php if ($key === 'applications'): $rows = (array) ($data['applications'] ?? []); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($rows) ?> RECORDS</small><h2>APPLICATIONS</h2></div><i data-lucide="files"></i></div><div class="management-table-wrap"><table class="updates-table"><thead><tr><th>Applicant</th><th>Device</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><strong><?= $escape($row['username'] ?? $row['discord_user_id'] ?? '') ?></strong><small><?= $escape($row['discord_user_id'] ?? '') ?></small></td><td><?= $escape(($row['device_name'] ?? '') ?: ($row['device_codename'] ?? 'Unknown')) ?></td><td><span class="status-badge status-<?= $escape($row['status'] ?? '') ?>"><?= $escape($row['status'] ?? '') ?></span></td><td><?= $escape(!empty($row['created_at']) ? date('j M Y, H:i', strtotime($row['created_at'])) : '') ?></td></tr><tr class="management-detail-row"><td colspan="4"><details><summary>Application #<?= (int) ($row['id'] ?? 0) ?> answers</summary><pre><?= $escape(json_encode($row['questions_answers'] ?? [], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></pre></details></td></tr><?php endforeach; ?></tbody></table></div></article>
    <?php elseif ($key === 'applicants'): $rows = (array) ($data['applicants'] ?? []); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($rows) ?> PEOPLE</small><h2>APPLICANTS</h2></div><i data-lucide="user-round-search"></i></div><div class="management-table-wrap"><table class="updates-table"><thead><tr><th>Applicant</th><th>Applications</th><th>Last result</th><th>Reapply</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><strong><?= $escape($row['username'] ?? '') ?></strong><small><?= $escape($row['discord_user_id'] ?? '') ?></small></td><td><?= (int) ($row['total_applications'] ?? 0) ?></td><td><span class="status-badge status-<?= $escape($row['last_application_status'] ?? '') ?>"><?= $escape($row['last_application_status'] ?? 'none') ?></span></td><td><?php if (empty($row['can_reapply'])): ?><?php $formStart('override_reapply'); ?><input type="hidden" name="user_id" value="<?= $escape($row['discord_user_id'] ?? '') ?>"><button class="secondary-button" type="submit"><i data-lucide="rotate-ccw"></i>Override</button></form><?php else: ?><span class="status-badge status-completed">Allowed</span><?php endif; ?></td><td><a class="icon-button" href="?feature=applicant-detail&amp;user_id=<?= $escape($row['discord_user_id'] ?? '') ?>" title="Application history"><i data-lucide="history"></i></a></td></tr><?php endforeach; ?></tbody></table></div></article>
    <?php elseif ($key === 'applicant-detail'): $rows = (array) ($data['applications'] ?? []); $summary = (array) ($data['summary'] ?? []); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($rows) ?> APPLICATIONS</small><h2><?= $escape(strtoupper((string) ($summary['username'] ?? 'APPLICANT'))) ?></h2></div><i data-lucide="history"></i></div><div class="management-list"><?php foreach ($rows as $row): ?><div class="management-record"><span><strong>#<?= (int) ($row['id'] ?? 0) ?> · <?= $escape($row['device_name'] ?? $row['device_codename'] ?? 'Unknown device') ?></strong><small><?= $escape(($row['status'] ?? '') . (!empty($row['reviewer_username']) ? ' · reviewed by ' . $row['reviewer_username'] : '') . (!empty($row['reason']) ? ' · ' . $row['reason'] : '')) ?></small><details><summary>Answers</summary><pre><?= $escape(json_encode($row['questions_answers'] ?? [], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></pre></details></span><time><?= $escape(!empty($row['created_at']) ? date('j M Y, H:i', strtotime((string) $row['created_at'])) : '') ?></time></div><?php endforeach; ?></div></article>
    <?php elseif ($key === 'questions'): $questions = array_values((array) ($data['questions'] ?? $data)); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($questions) ?> QUESTIONS</small><h2>APPLICATION FORM</h2></div><i data-lucide="list-checks"></i></div><?php $formStart('save_questions'); ?><div class="management-editor"><label>Questions JSON<textarea name="questions_json" rows="22" required><?= $escape(json_encode($questions, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></textarea><small>Each item requires a unique <code>key</code> and a <code>question</code>.</small></label><button class="primary-button" type="submit"><i data-lucide="save"></i>Save questions</button></div></form></article>
    <?php elseif ($key === 'users'): $rows = (array) ($data['users'] ?? []); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($rows) ?> USERS</small><h2>DISCORD ACCESS</h2></div><i data-lucide="users"></i></div><div class="management-list"><?php foreach ($rows as $row): ?><form class="management-inline-form management-user-form" method="post"><input type="hidden" name="csrf_token" value="<?= $escape(auth_csrf_token()) ?>"><input type="hidden" name="feature" value="users"><input type="hidden" name="user_id" value="<?= $escape($row['discord_id'] ?? '') ?>"><span class="management-user"><strong><?= $escape($row['username'] ?? '') ?></strong><small><?= $escape($row['discord_id'] ?? '') ?></small></span><label>Level<select name="permission_level"><?php foreach ([0 => 'User', 1 => 'Member', 2 => 'Moderator', 3 => 'Administrator'] as $level => $label): ?><option value="<?= $level ?>"<?= (int) ($row['permission_level'] ?? 0) === $level ? ' selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Blocked until<input type="datetime-local" name="blocked_until" value="<?= $escape(!empty($row['blocked_until']) ? date('Y-m-d\\TH:i', strtotime((string) $row['blocked_until'])) : '') ?>"></label><label class="management-check"><input type="checkbox" name="is_blocked" value="1"<?= !empty($row['is_blocked']) ? ' checked' : '' ?>>Blocked</label><a class="icon-button" href="?feature=user-permissions&amp;user_id=<?= $escape($row['discord_id'] ?? '') ?>" title="Command permissions"><i data-lucide="shield-check"></i></a><button class="icon-button" type="submit" name="action" value="update_user" title="Save user"><i data-lucide="save"></i></button><button class="icon-button danger-button" type="submit" name="action" value="delete_user" title="Delete user" onclick="return confirm('Delete this user?')"><i data-lucide="trash-2"></i></button></form><?php endforeach; ?></div></article>
    <?php elseif ($key === 'group-permissions'): $actions = (array) ($data['actions'] ?? []); $level = (int) ($data['permission_level'] ?? ($_GET['level'] ?? 3)); ?>
        <div class="management-actions"><a class="secondary-button" href="?feature=permission-templates"><i data-lucide="copy-check"></i>Permission templates</a></div><form class="management-level-picker" method="get"><input type="hidden" name="feature" value="group-permissions"><label>Permission group<select name="level" onchange="this.form.submit()"><?php foreach ([0 => 'User', 1 => 'Member', 2 => 'Moderator', 3 => 'Administrator'] as $value => $label): ?><option value="<?= $value ?>"<?= $level === $value ? ' selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label></form><article class="content-card management-card"><div class="card-heading"><div><small><?= count($actions) ?> COMMANDS</small><h2>GROUP PERMISSIONS</h2></div><i data-lucide="shield-check"></i></div><?php $formStart('save_group_permissions'); ?><input type="hidden" name="permission_level" value="<?= $level ?>"><div class="permission-grid"><?php foreach ($actions as $action): ?><label><input type="checkbox" name="allowed_actions[]" value="<?= $escape($action['action'] ?? '') ?>"<?= !empty($action['allowed']) ? ' checked' : '' ?>><span><strong><?= $escape($action['display_name'] ?? $action['command_name'] ?? '') ?></strong><small><?= $escape(($action['bot_type'] ?? '') . ' · ' . ($action['command_type'] ?? '')) ?></small></span></label><?php endforeach; ?></div><div class="management-actions"><button class="primary-button" type="submit"><i data-lucide="save"></i>Save permissions</button></div></form></article>
    <?php elseif ($key === 'user-permissions'): $actions = (array) ($data['actions'] ?? []); $targetUserId = (string) ($_GET['user_id'] ?? $_POST['user_id'] ?? ''); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($actions) ?> COMMANDS</small><h2>USER OVERRIDES</h2></div><i data-lucide="user-cog"></i></div><?php $formStart('save_user_permissions'); ?><input type="hidden" name="user_id" value="<?= $escape($targetUserId) ?>"><div class="permission-grid"><?php foreach ($actions as $action): ?><label><input type="checkbox" name="allowed_actions[]" value="<?= $escape($action['action'] ?? '') ?>"<?= !empty($action['allowed']) ? ' checked' : '' ?>><span><strong><?= $escape($action['display_name'] ?? $action['command_name'] ?? '') ?></strong><small><?= $escape(($action['bot_type'] ?? '') . ' · ' . ($action['command_type'] ?? '')) ?></small></span></label><?php endforeach; ?></div><div class="management-actions"><button class="primary-button" type="submit"><i data-lucide="save"></i>Save user permissions</button></div></form></article>
    <?php elseif ($key === 'permission-templates'): $templates = (array) ($data['templates'] ?? []); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($templates) ?> TEMPLATES</small><h2>PERMISSION TEMPLATES</h2></div><i data-lucide="copy-check"></i></div><?php $formStart('save_permission_templates'); ?><div class="management-editor"><label>Templates JSON<textarea name="templates_json" rows="22" required><?= $escape(json_encode($templates, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></textarea><small>Each template requires a name and an actions array.</small></label><button class="primary-button" type="submit"><i data-lucide="save"></i>Save templates</button></div></form></article>
    <?php elseif ($key === 'abuse'): $rows = (array) ($data['records'] ?? []); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($rows) ?> RECORDS</small><h2>ABUSE LOG</h2></div><i data-lucide="shield-alert"></i></div><div class="management-list"><?php foreach ($rows as $row): ?><div class="management-record"><span><strong><?= $escape($row['username'] ?? 'Unknown') ?></strong><small><?= $escape(($row['severity'] ?? '') . ' · ' . ($row['reason'] ?? '')) ?></small></span><?php if (empty($row['is_resolved'])): ?><?php $formStart('resolve_abuse'); ?><input type="hidden" name="record_id" value="<?= (int) ($row['id'] ?? 0) ?>"><button class="secondary-button" type="submit"><i data-lucide="check"></i>Resolve</button></form><?php else: ?><span class="status-badge status-completed">Resolved</span><?php endif; ?></div><?php endforeach; ?></div></article>
    <?php elseif ($key === 'cache'): $rows = (array) ($data['entries'] ?? []); ?>
        <div class="management-actions"><?php foreach (['maintainers', 'devices', 'donations', 'all'] as $type): ?><?php $formStart('refresh_cache'); ?><input type="hidden" name="cache_type" value="<?= $type ?>"><button class="secondary-button" type="submit"><i data-lucide="refresh-cw"></i><?= $escape(ucfirst($type)) ?></button></form><?php endforeach; ?></div><article class="content-card management-card"><div class="card-heading"><div><small><?= count($rows) ?> ENTRIES</small><h2>BOT CACHE</h2></div><i data-lucide="database-zap"></i></div><div class="management-list"><?php foreach ($rows as $row): ?><div class="management-record"><span><strong><?= $escape($row['key'] ?? '') ?></strong><small><?= number_format((int) ($row['size'] ?? 0)) ?> bytes · <?= $escape($row['type'] ?? '') ?></small></span><?php $formStart('delete_cache'); ?><input type="hidden" name="cache_key" value="<?= $escape($row['key'] ?? '') ?>"><button class="icon-button" type="submit" title="Delete cache entry"><i data-lucide="trash-2"></i></button></form></div><?php endforeach; ?></div></article>
    <?php elseif ($key === 'privacy-requests'): $rows = (array) ($data['requests'] ?? []); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($rows) ?> REQUESTS</small><h2>PRIVACY QUEUE</h2></div><i data-lucide="user-round-check"></i></div><div class="management-list"><?php foreach ($rows as $row): ?><?php $formStart('update_privacy'); ?><input type="hidden" name="request_id" value="<?= $escape($row['id'] ?? '') ?>"><span class="management-user"><strong><?= $escape($row['type'] ?? 'Privacy request') ?></strong><small><?= $escape($row['discord_user_id'] ?? $row['email'] ?? '') ?></small></span><select name="status"><?php foreach (['open', 'in_progress', 'completed', 'rejected'] as $status): ?><option value="<?= $status ?>"<?= ($row['status'] ?? 'open') === $status ? ' selected' : '' ?>><?= $escape(ucwords(str_replace('_', ' ', $status))) ?></option><?php endforeach; ?></select><input name="note" maxlength="2000" value="<?= $escape($row['staff_note'] ?? '') ?>" placeholder="Staff note"><button class="icon-button" type="submit" title="Save request"><i data-lucide="save"></i></button></form><?php endforeach; ?></div></article>
    <?php elseif ($key === 'action-logs'): $rows = (array) ($data['user_actions'] ?? []); ?>
        <article class="content-card management-card"><div class="card-heading"><div><small><?= count($rows) ?> ENTRIES</small><h2>USER ACTIONS</h2></div><i data-lucide="list-restart"></i></div><div class="management-list"><?php foreach ($rows as $row): ?><div class="management-record"><span><strong><?= $escape(($row['username'] ?? 'Unknown') . ' · ' . ($row['action'] ?? '')) ?></strong><small><?= $escape($row['description'] ?? '') ?></small></span><time><?= $escape(!empty($row['created_at']) ? date('j M, H:i', strtotime($row['created_at'])) : '') ?></time></div><?php endforeach; ?></div></article>
    <?php elseif ($key === 'system-logs'): $logs = (array) ($data['system'] ?? []); ?>
        <div class="feature-directory"><?php foreach ($logs as $service => $rows): ?><section class="feature-group"><div class="feature-group-heading"><span><small><?= count((array) $rows) ?> ENTRIES</small><h2><?= $escape(strtoupper(str_replace('_', ' ', $service))) ?></h2></span><i data-lucide="scroll-text"></i></div><div class="management-list"><?php foreach ((array) $rows as $row): ?><div class="management-record"><span><strong><?= $escape($row['timestamp'] ?? '') ?></strong><small><?= $escape($row['message'] ?? '') ?></small></span></div><?php endforeach; ?></div></section><?php endforeach; ?></div>
    <?php endif; ?>
</section>
<?php dashboard_footer(); ?>